     1	package shop.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.util.Optional;
     5	
     6	/** Delivery region: insurance pricing and extra dispatch days of the distribution center. */
     7	public enum Region {
     8	    SOUTHEAST("0.01", null, 0),
     9	    SOUTH("0.01", null, 0),
    10	    MIDWEST("0.015", null, 0),
    11	    NORTH("0.025", "30.00", 3),
    12	    NORTHEAST("0.02", "30.00", 2);
    13	
    14	    private final BigDecimal insuranceRate;
    15	    private final BigDecimal insuranceCap;
    16	    private final int extraDispatchDays;
    17	
    18	    Region(String insuranceRate, String insuranceCap, int extraDispatchDays) {
    19	        this.insuranceRate = new BigDecimal(insuranceRate);
    20	        this.insuranceCap = insuranceCap == null ? null : new BigDecimal(insuranceCap);
    21	        this.extraDispatchDays = extraDispatchDays;
    22	    }
    23	
    24	    public BigDecimal insurance(BigDecimal productsSubtotal) {
    25	        BigDecimal value = Money.round(productsSubtotal.multiply(insuranceRate));
    26	        return insuranceCap != null && value.compareTo(insuranceCap) > 0 ? insuranceCap : value;
    27	    }
    28	
    29	    public int extraDispatchDays() {
    30	        return extraDispatchDays;
    31	    }
    32	
    33	    public static Optional<Region> parse(String code) {
    34	        for (Region r : values()) {
    35	            if (r.name().equals(code)) {
    36	                return Optional.of(r);
    37	            }
    38	        }
    39	        return Optional.empty();
    40	    }
    41	}
