  1	package shop.app;
  2	
  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import java.math.BigDecimal;
  5	import java.util.ArrayList;
  6	import java.util.HashSet;
  7	import java.util.List;
  8	import java.util.Map;
  9	import java.util.Set;
 10	import shop.db.Database;
 11	import shop.domain.ApiException;
 12	import shop.domain.CartLine;
 13	import shop.domain.ClubTier;
 14	import shop.domain.Coupon;
 15	import shop.domain.Money;
 16	import shop.domain.OrderItem;
 17	import shop.domain.PaymentMethod;
 18	import shop.domain.Product;
 19	import shop.domain.Region;
 20	import shop.domain.Rules;
 21	import shop.domain.ShippingMethod;
 22	import shop.domain.Summary;
 23	
 24	/** Validates a purchase and computes its summary. Shared by the summary endpoint and order registration. */
 25	public final class CheckoutService {
 26	    public record Checkout(String cpf, String email, List<OrderItem> items, Summary summary) {
 27	    }
 28	
 29	    private final Database db;
 30	    private final Rules rules;
 31	
 32	    public CheckoutService(Database db, Rules rules) {
 33	        this.db = db;
 34	        this.rules = rules;
 35	    }
 36	
 37	    public Checkout prepare(JsonNode body) {
 38	        // 1. basic shape
 39	        if (!body.isObject()) {
 40	            throw invalid("INVALID_ORDER");
 41	        }
 42	        JsonNode customer = body.path("customer");
 43	        String cpf = text(customer.path("cpf"));
 44	        String email = text(customer.path("email"));
 45	        List<OrderItem> items = parseItems(body.path("items"));
 46	        if (cpf == null || email == null) {
 47	            throw invalid("INVALID_ORDER");
 48	        }
 49	
 50	        // 2-4. products
 51	        List<CartLine> lines = loadLines(items);
 52	
 53	        // 5-8. simple fields
 54	        ClubTier tier = rules.tiers().find(text(body.path("clubTier")))
 55	                .orElseThrow(() -> invalid("INVALID_CLUB_TIER"));
 56	        Region region = Region.parse(text(body.path("region"))).orElseThrow(() -> invalid("INVALID_REGION"));
 57	        String zip = text(body.path("zipCode"));
 58	        if (zip == null || !zip.matches("[0-9]{8}")) {
 59	            throw invalid("INVALID_ZIP_CODE");
 60	        }
 61	        ShippingMethod shipping = rules.shipping().find(text(body.path("shippingMethod")))
 62	                .orElseThrow(() -> invalid("INVALID_SHIPPING_METHOD"));
 63	
 64	        // 9-10. shipping quote
 65	        BigDecimal subtotal = Money.round(lines.stream().map(CartLine::total).reduce(BigDecimal.ZERO, BigDecimal::add));
 66	        BigDecimal weightKg = lines.stream().map(CartLine::weightKg).reduce(BigDecimal.ZERO, BigDecimal::add);
 67	        ShippingMethod.Quote quote = shipping.quote(new ShippingMethod.Request(zip, weightKg, region));
 68	        BigDecimal shippingCost = tier.freeShipping() && shipping.coveredByTierFreeShipping()
 69	                ? Money.ZERO : Money.round(quote.cost());
 70	
 71	        // 11-12. coupon
 72	        JsonNode couponNode = body.path("coupon");
 73	        boolean couponUsed = !couponNode.isMissingNode() && !couponNode.isNull();
 74	        BigDecimal couponDiscount = Money.ZERO;
 75	        if (couponUsed) {
 76	            Coupon coupon = rules.coupons().find(couponNode.isTextual() ? couponNode.asText() : null)
 77	                    .orElseThrow(() -> invalid("INVALID_COUPON"));
 78	            Coupon.Context context = new Coupon.Context(cpf, lines, subtotal, shipping, shippingCost,
 79	                    () -> !db.tx(d -> d.hasCompletedPurchase(cpf)));
 80	            BigDecimal cap = Money.round(subtotal.multiply(rules.couponDiscountCap()));
 81	            couponDiscount = Money.round(coupon.discount(context).min(cap));
 82	        }
 83	
 84	        // 13-15. payment
 85	        PaymentMethod payment = rules.payments().find(text(body.path("paymentMethod")))
 86	                .orElseThrow(() -> invalid("INVALID_PAYMENT_METHOD"));
 87	        int installments = parseInstallments(body.path("installments"), payment);
 88	        BigDecimal insurance = region.insurance(subtotal);
 89	        BigDecimal orderTotal = subtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
 90	        payment.checkAvailable(orderTotal);
 91	        PaymentMethod.Settlement settlement = payment.settle(orderTotal, installments, couponUsed);
 92	
 93	        Summary summary = new Summary(subtotal, couponDiscount, shippingCost, quote.days(), insurance,
 94	                Money.round(settlement.finalTotal().subtract(orderTotal)), Money.round(settlement.finalTotal()),
 95	                installments, Money.round(settlement.installmentAmount()), tier.credit(subtotal),
 96	                tier.gift(subtotal));
 97	        return new Checkout(cpf, email, items, summary);
 98	    }
 99	
100	    private static List<OrderItem> parseItems(JsonNode node) {
101	        if (!node.isArray() || node.isEmpty()) {
102	            throw invalid("INVALID_ORDER");
103	        }
104	        List<OrderItem> items = new ArrayList<>();
105	        Set<String> seen = new HashSet<>();
106	        for (JsonNode item : node) {
107	            String sku = text(item.path("sku"));
108	            JsonNode quantity = item.path("quantity");
109	            if (sku == null || !seen.add(sku) || !quantity.isIntegralNumber() || !quantity.canConvertToInt()
110	                    || quantity.intValue() <= 0) {
111	                throw invalid("INVALID_ORDER");
112	            }
113	            items.add(new OrderItem(sku, quantity.intValue()));
114	        }
115	        return items;
116	    }
117	
118	    private List<CartLine> loadLines(List<OrderItem> items) {
119	        Map<String, Product> products = db.tx(d -> d.products(items.stream().map(OrderItem::sku).toList()));
120	        List<CartLine> lines = new ArrayList<>();
121	        for (OrderItem item : items) {
122	            Product p = products.get(item.sku());
123	            if (p == null) {
124	                throw invalid("UNKNOWN_PRODUCT");
125	            }
126	            lines.add(new CartLine(p, item.quantity()));
127	        }
128	        if (lines.stream().anyMatch(l -> l.product().discontinued())) {
129	            throw invalid("PRODUCT_DISCONTINUED");
130	        }
131	        if (lines.stream().anyMatch(l -> l.product().stock() < l.quantity())) {
132	            throw invalid("INSUFFICIENT_STOCK");
133	        }
134	        return lines;
135	    }
136	
137	    private static int parseInstallments(JsonNode node, PaymentMethod payment) {
138	        int installments = 1;
139	        if (!node.isMissingNode() && !node.isNull()) {
140	            if (!node.isIntegralNumber() || !node.canConvertToInt()) {
141	                throw invalid("INVALID_INSTALLMENTS");
142	            }
143	            installments = node.intValue();
144	        }
145	        if (!payment.acceptsInstallments(installments)) {
146	            throw invalid("INVALID_INSTALLMENTS");
147	        }
148	        return installments;
149	    }
150	
151	    /** The text of a JSON string, or null if absent, not a string or blank. */
152	    static String text(JsonNode node) {
153	        return node.isTextual() && !node.asText().isBlank() ? node.asText() : null;
154	    }
155	
156	    private static ApiException invalid(String code) {
157	        return ApiException.unprocessable(code);
158	    }
159	}
160	package shop.app;
161	
162	import com.fasterxml.jackson.databind.JsonNode;
163	import java.math.BigDecimal;
164	import java.net.URI;
165	import java.net.URLEncoder;
166	import java.net.http.HttpClient;
167	import java.net.http.HttpRequest;
168	import java.net.http.HttpResponse;
169	import java.nio.charset.StandardCharsets;
170	import java.time.Duration;
171	import java.util.Optional;
172	import java.util.concurrent.CompletableFuture;
173	import java.util.concurrent.TimeUnit;
174	import shop.domain.CarrierGateway;
175	import shop.domain.Json;
176	
177	/** Quotes freight on the TransLog website. Anything unexpected, or slower than 2 seconds, means "down". */
178	public final class TransLogClient implements CarrierGateway {
179	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
180	
181	    private final String baseUrl;
182	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
183	
184	    public TransLogClient(String baseUrl) {
185	        this.baseUrl = baseUrl == null ? "" : baseUrl.replaceAll("/+$", "");
186	    }
187	
188	    @Override
189	    public Optional<Quote> quote(String zipCode, int weightGrams, String service) {
190	        CompletableFuture<HttpResponse<String>> future = null;
191	        try {
192	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + URLEncoder.encode(zipCode, StandardCharsets.UTF_8)
193	                    + "&weight_g=" + weightGrams + "&service=" + URLEncoder.encode(service, StandardCharsets.UTF_8));
194	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
195	            future = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
196	            HttpResponse<String> response = future.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
197	            if (response.statusCode() != 200) {
198	                throw new UnavailableException("TransLog answered " + response.statusCode(), null);
199	            }
200	            return parse(Json.MAPPER.readTree(response.body()));
201	        } catch (UnavailableException e) {
202	            throw e;
203	        } catch (InterruptedException e) {
204	            Thread.currentThread().interrupt();
205	            throw new UnavailableException("interrupted", e);
206	        } catch (Exception e) {
207	            throw new UnavailableException("TransLog failed", e);
208	        } finally {
209	            if (future != null) {
210	                future.cancel(true);
211	            }
212	        }
213	    }
214	
215	    private static Optional<Quote> parse(JsonNode body) {
216	        if (body == null || !body.isObject()) {
217	            throw new UnavailableException("unexpected TransLog body", null);
218	        }
219	        if (body.has("error")) {
220	            if (body.get("error").isTextual() && "ZIP_NOT_SERVED".equals(body.get("error").asText())) {
221	                return Optional.empty();
222	            }
223	            throw new UnavailableException("TransLog error " + body.get("error"), null);
224	        }
225	        JsonNode cents = body.path("price_cents");
226	        JsonNode hours = body.path("eta_hours");
227	        if (!cents.isIntegralNumber() || !hours.isIntegralNumber() || cents.asLong() < 0 || hours.asLong() < 0
228	                || !hours.canConvertToInt()) {
229	            throw new UnavailableException("unexpected TransLog quote", null);
230	        }
231	        BigDecimal cost = BigDecimal.valueOf(cents.asLong(), 2);
232	        int days = (int) ((hours.asLong() + 23) / 24);
233	        return Optional.of(new Quote(cost, days));
234	    }
235	}
236	package shop;
237	
238	import com.zaxxer.hikari.HikariConfig;
239	import com.zaxxer.hikari.HikariDataSource;
240	import java.time.Clock;
241	import java.util.List;
242	import shop.app.CheckoutService;
243	import shop.app.CreditEffect;
244	import shop.app.Notifier;
245	import shop.app.OrderService;
246	import shop.app.PaymentApprovedNoticeEffect;
247	import shop.app.QueryService;
248	import shop.app.TransLogClient;
249	import shop.db.Database;
250	import shop.db.Schema;
251	import shop.domain.CarrierGateway;
252	import shop.domain.Rules;
253	import shop.web.Api;
254	
255	public final class Main {
256	    private Main() {
257	    }
258	
259	    /** Wires the whole service on top of a database. */
260	    public static Api wire(Database db, CarrierGateway carrier, Clock clock) {
261	        Rules rules = Rules.standard(carrier);
262	        CheckoutService checkout = new CheckoutService(db, rules);
263	        Notifier notifier = new Notifier();
264	        OrderService orders = new OrderService(db, checkout, clock, notifier,
265	                List.of(new CreditEffect(), new PaymentApprovedNoticeEffect(notifier)));
266	        return new Api(checkout, orders, new QueryService(db));
267	    }
268	
269	    public static void main(String[] args) throws Exception {
270	        HikariConfig config = new HikariConfig();
271	        config.setJdbcUrl(System.getenv("DB_URL"));
272	        config.setUsername(System.getenv("DB_USER"));
273	        config.setPassword(System.getenv("DB_PASSWORD"));
274	        config.setMaximumPoolSize(10);
275	        config.setInitializationFailTimeout(-1);
276	        HikariDataSource dataSource = new HikariDataSource(config);
277	
278	        initSchemaWithRetry(dataSource);
279	
280	        String port = System.getenv("PORT");
281	        Database db = new Database(dataSource);
282	        wire(db, new TransLogClient(System.getenv("TRANSLOG_URL")), Clock.systemUTC())
283	                .create().start(port == null || port.isBlank() ? 8080 : Integer.parseInt(port.trim()));
284	    }
285	
286	    private static void initSchemaWithRetry(HikariDataSource dataSource) throws Exception {
287	        long deadline = System.currentTimeMillis() + 120_000;
288	        while (true) {
289	            try {
290	                Schema.init(dataSource);
291	                return;
292	            } catch (Exception e) {
293	                if (System.currentTimeMillis() > deadline) {
294	                    throw e;
295	                }
296	                System.err.println("Database not ready, retrying: " + e.getMessage());
297	                Thread.sleep(2000);
298	            }
299	        }
300	    }
301	}

