     1	package shop.app;
     2	
     3	import com.fasterxml.jackson.databind.JsonNode;
     4	import java.sql.SQLException;
     5	import java.time.Clock;
     6	import java.time.Duration;
     7	import java.time.Instant;
     8	import java.time.OffsetDateTime;
     9	import java.time.format.DateTimeParseException;
    10	import java.time.temporal.ChronoUnit;
    11	import java.util.List;
    12	import java.util.Map;
    13	import java.util.UUID;
    14	import shop.db.Dao;
    15	import shop.db.Database;
    16	import shop.domain.ApiException;
    17	import shop.domain.NotificationType;
    18	import shop.domain.Order;
    19	import shop.domain.OrderItem;
    20	import shop.domain.OrderLifecycle;
    21	import shop.domain.OrderLifecycle.Operation;
    22	import shop.domain.OrderStatus;
    23	import shop.domain.Product;
    24	
    25	public final class OrderService {
    26	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
    27	    private static final String OK = "OK";
    28	    private static final String EXPIRED = "ORDER_EXPIRED";
    29	    private static final String NO_STOCK = "INSUFFICIENT_STOCK";
    30	
    31	    /** Result of a payment notice: the order, or the code of a refusal that was nevertheless persisted. */
    32	    public record PaymentResult(Order order, String error) {
    33	    }
    34	
    35	    private final Database db;
    36	    private final CheckoutService checkout;
    37	    private final Clock clock;
    38	    private final Notifier notifier;
    39	    private final List<PaidOrderEffect> effects;
    40	
    41	    public OrderService(Database db, CheckoutService checkout, Clock clock, Notifier notifier,
    42	                        List<PaidOrderEffect> effects) {
    43	        this.db = db;
    44	        this.checkout = checkout;
    45	        this.clock = clock;
    46	        this.notifier = notifier;
    47	        this.effects = effects;
    48	    }
    49	
    50	    public Order register(JsonNode body) {
    51	        CheckoutService.Checkout c = checkout.prepare(body);
    52	        Order order = new Order(UUID.randomUUID().toString(), c.cpf(), c.email(), OrderStatus.AWAITING_PAYMENT,
    53	                clock.instant().truncatedTo(ChronoUnit.SECONDS), c.summary(), c.items(), null);
    54	        return db.tx(d -> {
    55	            d.ensureCustomer(c.cpf(), c.email());
    56	            d.insertOrder(order);
    57	            return order;
    58	        });
    59	    }
    60	
    61	    public Order get(String id) {
    62	        return db.tx(d -> d.order(id, false).orElseThrow(() -> ApiException.notFound("ORDER_NOT_FOUND")));
    63	    }
    64	
    65	    public PaymentResult pay(String id, JsonNode body) {
    66	        return db.tx(d -> {
    67	            Order order = lock(d, id);
    68	            String transactionId = CheckoutService.text(body.path("transactionId"));
    69	            Instant paidAt = parseInstant(body.path("paidAt"));
    70	            if (transactionId == null || paidAt == null) {
    71	                throw ApiException.unprocessable("INVALID_ORDER");
    72	            }
    73	            var previous = d.paymentOutcome(id, transactionId);
    74	            if (previous.isPresent()) {
    75	                return result(order, previous.get());
    76	            }
    77	            OrderLifecycle.require(order.status(), Operation.PAY);
    78	
    79	            if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
    80	                return refuse(d, order, transactionId, EXPIRED);
    81	            }
    82	            Map<String, Product> products = d.lockProducts(order.items().stream().map(OrderItem::sku).toList());
    83	            for (OrderItem item : order.items()) {
    84	                Product p = products.get(item.sku());
    85	                if (p == null || p.stock() < item.quantity()) {
    86	                    return refuse(d, order, transactionId, NO_STOCK);
    87	                }
    88	            }
    89	            for (OrderItem item : order.items()) {
    90	                d.adjustStock(item.sku(), -item.quantity());
    91	            }
    92	            d.updateStatus(id, OrderStatus.PAID);
    93	            Order paid = withStatus(order, OrderStatus.PAID);
    94	            for (PaidOrderEffect effect : effects) {
    95	                effect.onPaid(d, paid);
    96	            }
    97	            d.recordPaymentOutcome(id, transactionId, OK);
    98	            return new PaymentResult(paid, null);
    99	        });
   100	    }
   101	
   102	    public Order ship(String id, JsonNode body) {
   103	        return db.tx(d -> {
   104	            Order order = lock(d, id);
   105	            String trackingCode = CheckoutService.text(body.path("trackingCode"));
   106	            if (trackingCode == null) {
   107	                throw ApiException.unprocessable("INVALID_ORDER");
   108	            }
   109	            OrderStatus next = OrderLifecycle.require(order.status(), Operation.SHIP);
   110	            d.updateStatus(id, next);
   111	            d.updateTrackingCode(id, trackingCode);
   112	            Order shipped = new Order(order.id(), order.cpf(), order.email(), next, order.createdAt(),
   113	                    order.summary(), order.items(), trackingCode);
   114	            notifier.notify(d, shipped, NotificationType.ORDER_SHIPPED);
   115	            return shipped;
   116	        });
   117	    }
   118	
   119	    public Order deliver(String id) {
   120	        return db.tx(d -> {
   121	            Order order = lock(d, id);
   122	            OrderStatus next = OrderLifecycle.require(order.status(), Operation.DELIVER);
   123	            d.updateStatus(id, next);
   124	            return withStatus(order, next);
   125	        });
   126	    }
   127	
   128	    public Order cancel(String id) {
   129	        return db.tx(d -> {
   130	            Order order = lock(d, id);
   131	            OrderStatus next = OrderLifecycle.require(order.status(), Operation.CANCEL);
   132	            if (order.status() == OrderStatus.PAID) {
   133	                Map<String, Product> locked = d.lockProducts(order.items().stream().map(OrderItem::sku).toList());
   134	                for (OrderItem item : order.items()) {
   135	                    if (locked.containsKey(item.sku())) {
   136	                        d.adjustStock(item.sku(), item.quantity());
   137	                    }
   138	                }
   139	                for (PaidOrderEffect effect : effects) {
   140	                    effect.onPaidOrderCancelled(d, order);
   141	                }
   142	            }
   143	            return markCancelled(d, order, next);
   144	        });
   145	    }
   146	
   147	    private PaymentResult refuse(Dao d, Order order, String transactionId, String code) throws SQLException {
   148	        Order cancelled = markCancelled(d, order, OrderStatus.CANCELLED);
   149	        d.recordPaymentOutcome(order.id(), transactionId, code);
   150	        return new PaymentResult(cancelled, code);
   151	    }
   152	
   153	    private Order markCancelled(Dao d, Order order, OrderStatus next) throws SQLException {
   154	        d.updateStatus(order.id(), next);
   155	        Order cancelled = withStatus(order, next);
   156	        notifier.notify(d, cancelled, NotificationType.ORDER_CANCELLED);
   157	        return cancelled;
   158	    }
   159	
   160	    private static PaymentResult result(Order order, String outcome) {
   161	        return OK.equals(outcome) ? new PaymentResult(order, null) : new PaymentResult(order, outcome);
   162	    }
   163	
   164	    private static Order lock(Dao d, String id) throws SQLException {
   165	        return d.order(id, true).orElseThrow(() -> ApiException.notFound("ORDER_NOT_FOUND"));
   166	    }
